begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select api.worker_mail_bootstrap('test','sender@example.invalid','De Poorten','reply@example.invalid');
create temp table mail_test(config uuid,outbox uuid,envelope jsonb,actor uuid default 'f0000000-0000-0000-0000-000000000001');
insert into mail_test(config) select (api.worker_mail_config('test')->>'id')::uuid;
select is(api.worker_mail_config('test')->>'provider','sendgrid','bootstrap retains the effective legacy provider');
select api.mail_admin_command('test',(select actor from mail_test),'duindorp-halloween-2026','save',0,null,'{"provider":"resend","fromEmail":"sender@example.invalid","fromName":"De Poorten","replyTo":"reply@example.invalid"}');
update mail_test set config=(select draft_id from app_private.mail_config_heads where environment='test');
select is(api.worker_mail_config('test')->>'provider','sendgrid','saving a Resend draft leaves Auth on legacy config');
select throws_ok($$select api.mail_admin_command('test','a0000000-0000-0000-0000-000000000001','duindorp-halloween-2026','save',1,null,'{}')$$,'42501','NOT_AUTHORIZED','ordinary authenticated users cannot manage system mail');
select throws_ok($$select api.mail_admin_command('test',(select actor from mail_test),'duindorp-halloween-2026','save',0,null,'{}')$$,'40001','CONFIG_VERSION_CONFLICT','stale drafts cannot overwrite a parallel edit');
select api.mail_admin_command('test',(select actor from mail_test),'duindorp-halloween-2026','check',1,(select config from mail_test),null,(select jsonb_build_object('ready',true,'configHash',config_hash,'credentialHash',repeat('c',64),'webhookKeyHash',repeat('f',64)) from app_private.mail_config_versions where id=(select config from mail_test)));
select throws_ok($$select api.mail_admin_command('test',(select actor from mail_test),'duindorp-halloween-2026','activate',1,(select config from mail_test),null,'{"confirmed":true}')$$,'P0001','SUPPRESSION_IMPORT_REQUIRED','activation requires the reviewed legacy suppression import');
select api.worker_import_mail_suppressions('test','[]',repeat('a',64),true);
select throws_ok($$select api.mail_admin_command('test',(select actor from mail_test),'duindorp-halloween-2026','activate',1,(select config from mail_test),null,'{"confirmed":true}')$$,'P0001','VERIFIED_DRAFT_TEST_REQUIRED','present secrets/checks alone never disable working Auth');
-- A controlled draft test runs through the one application outbox.
update mail_test set outbox=api.mail_admin_test('test',actor,'duindorp-halloween-2026',1,'test@example.invalid','test-command-001');
select is(api.mail_admin_test('test',(select actor from mail_test),'duindorp-halloween-2026',1,'test@example.invalid','other-tab-command-001'),(select outbox from mail_test),'two tabs share one test delivery');
select is(api.mail_admin_test('test',(select actor from mail_test),'duindorp-halloween-2026',1,'test@example.invalid','test-command-001'),(select outbox from mail_test),'HTTP retry reuses the durable command receipt');
update app_private.email_outbox set status='processing',attempts=1 where id=(select outbox from mail_test);
update mail_test set envelope=api.worker_mail_prepare('test','test-envelope',config,outbox,'test','mail_provider_test','test@example.invalid','{"text":"frozen body"}',repeat('b',64),repeat('c',64));
select is((select envelope->>'dispatch' from mail_test),'true','first attempt durably owns the envelope before provider dispatch');
select is((api.worker_mail_prepare('test','test-envelope',(select config from mail_test),(select outbox from mail_test),'test','mail_provider_test','test@example.invalid','{"text":"changed"}',repeat('z',64),repeat('c',64))->>'dispatch'),'false','parallel dispatch cannot acquire a live envelope lease');
select is(api.worker_store_resend_event('test','msg-before-worker','e07af2b0-ad41-4b87-81f1-6f633c83e87f','email.delivered',now(),'test@example.invalid',null,repeat('f',64)),true,'webhook before provider ID persistence is durably stored');
select ok((select outbox_id is null from app_private.email_events where provider='resend' and provider_event_id='msg-before-worker'),'early event is unlinked; a tag cannot take control of an outbox row');
select api.worker_mail_finish((select (envelope->>'id')::uuid from mail_test),(select (envelope->>'claim_token')::uuid from mail_test),'accepted','e07af2b0-ad41-4b87-81f1-6f633c83e87f');
select is((select status::text from app_private.email_outbox where id=(select outbox from mail_test)),'delivered','provider acknowledgement reconciles the early webhook once');
select is((select outbox_id from app_private.email_events where provider_event_id='msg-before-worker'),(select outbox from mail_test),'true provider ID and recipient establish the relation');
select is(api.worker_store_resend_event('test','msg-before-worker','e07af2b0-ad41-4b87-81f1-6f633c83e87f','email.delivered',now(),'test@example.invalid',null,repeat('f',64)),false,'duplicate Svix delivery is an acknowledged no-op');
select api.worker_store_resend_event('test','msg-late-sent','e07af2b0-ad41-4b87-81f1-6f633c83e87f','email.sent',now()-interval '2 minutes','test@example.invalid');
select api.worker_store_resend_event('test','msg-late-delay','e07af2b0-ad41-4b87-81f1-6f633c83e87f','email.delivery_delayed',now(),'test@example.invalid');
select is((select delivery_status from app_private.mail_envelopes where id=(select (envelope->>'id')::uuid from mail_test)),'delivered','late sent or delayed events cannot regress delivery');
select api.worker_store_resend_event('production','msg-wrong-environment','e07af2b0-ad41-4b87-81f1-6f633c83e87f','email.failed',now(),'test@example.invalid');
select api.worker_store_resend_event('test','msg-wrong-recipient','e07af2b0-ad41-4b87-81f1-6f633c83e87f','email.failed',now(),'other@example.invalid');
select is((select delivery_status from app_private.mail_envelopes where id=(select (envelope->>'id')::uuid from mail_test)),'delivered','wrong environment/recipient events have no projection authority');
update app_private.mail_envelopes set accepted_at=now()-interval '31 minutes' where logical_key='test-envelope';
select throws_ok($$select api.mail_admin_command('test',(select actor from mail_test),'duindorp-halloween-2026','activate',1,(select config from mail_test),null,'{"confirmed":true}')$$,'P0001','VERIFIED_DRAFT_TEST_REQUIRED','an old successful test is not proof of current sending access');
update app_private.mail_envelopes set accepted_at=clock_timestamp() where logical_key='test-envelope';
select api.mail_admin_command('test',(select actor from mail_test),'duindorp-halloween-2026','activate',1,(select config from mail_test),null,'{"confirmed":true}');
select is(api.worker_mail_config('test')->>'provider','resend','only checked, imported, webhook-confirmed configuration becomes active');
select api.worker_store_resend_event('test','msg-complaint-after-delivery','e07af2b0-ad41-4b87-81f1-6f633c83e87f','email.complained',now(),'test@example.invalid','RESEND_COMPLAINED');
select is((select delivery_status from app_private.mail_envelopes where id=(select (envelope->>'id')::uuid from mail_test)),'complained','complaint after delivery is retained separately');
select ok(exists(select 1 from app_private.mail_suppressions where environment='test' and recipient_hash=extensions.digest('test@example.invalid','sha256')),'complaint applies durable suppression without changing consent');
select api.worker_update_outbox((select outbox from mail_test),'deferred',null,'late-worker',now());
select is((select status::text from app_private.email_outbox where id=(select outbox from mail_test)),'delivered','late worker update cannot make accepted/delivered mail claimable');
select is(api.worker_store_email_event('msg-before-worker',(select outbox from mail_test),'bounce',now()),false,'legacy SendGrid callback cannot control a Resend row');
-- Compatibility claims made by an old worker cannot become unlabelled Resend retries.
with inserted as(insert into app_private.email_outbox(dedupe_key,message_type,recipient_ref,recipient_email,payload,status) values('rolling-legacy-claim','registration_received','fixture','legacy-rollout@example.invalid','{}','pending') returning id)
update mail_test set outbox=inserted.id from inserted;
select api.worker_claim_outbox(50,10);
select is((select provider from app_private.email_outbox where id=(select outbox from mail_test)),'sendgrid','pre-envelope workers retain explicit legacy provider identity during rollout');
select throws_ok($$select api.worker_mail_prepare('test','mail/legacy-rollout/1',(select config from mail_test),(select outbox from mail_test),'transactional','registration_received','legacy-rollout@example.invalid','{}',repeat('d',64),repeat('c',64))$$,'P0001','LEGACY_ATTEMPT_REQUIRES_RECONCILIATION','a begun legacy attempt is never retried across providers');
-- All terminal provider outcomes retain transport acceptance and never enqueue a mail.
create temp table event_cases(kind text,recipient text,provider_id text default gen_random_uuid()::text,envelope jsonb);
insert into event_cases(kind,recipient) values('email.bounced','bounce@example.invalid'),('email.failed','failure@example.invalid'),('email.suppressed','suppressed@example.invalid');
update event_cases set envelope=api.worker_mail_prepare('test',kind,(select config from mail_test),null,'auth','auth_otp',recipient,null,repeat('d',64),repeat('c',64));
select api.worker_mail_finish((envelope->>'id')::uuid,(envelope->>'claim_token')::uuid,'accepted',provider_id) from event_cases;
select api.worker_store_resend_event('test','msg-'||kind,provider_id,kind,now(),recipient) from event_cases;
select is((select delivery_status from app_private.mail_envelopes where id=(event_cases.envelope->>'id')::uuid),replace(kind,'email.',''),kind||' has its own durable delivery projection') from event_cases;
select ok(not exists(select 1 from app_private.mail_envelopes where logical_key in(select kind from event_cases) and status<>'accepted'),'provider delivery failures do not relinquish transport acceptance');
with inserted as(insert into app_private.email_outbox(dedupe_key,message_type,recipient_ref,recipient_email,payload,status,attempts) values('resend-delay-fixture','registration_received','fixture','delay@example.invalid','{}','processing',1) returning id)
update mail_test set outbox=inserted.id from inserted;
update mail_test set envelope=api.worker_mail_prepare('test','mail/delay/1',config,outbox,'transactional','registration_received','delay@example.invalid','{"text":"frozen"}',repeat('d',64),repeat('c',64));
select api.worker_mail_finish((select (envelope->>'id')::uuid from mail_test),(select (envelope->>'claim_token')::uuid from mail_test),'accepted','9607af2b-ad41-4b87-81f1-6f633c83e87f');
select api.worker_store_resend_event('test','msg-delay-before-delivery','9607af2b-ad41-4b87-81f1-6f633c83e87f','email.delivery_delayed',now(),'delay@example.invalid');
select is((select status::text from app_private.email_outbox where id=(select outbox from mail_test)),'accepted','provider delay leaves an ordinary transactional outbox accepted');
select is((select count(*)::integer from api.worker_claim_outbox(50,10,'test') where id=(select outbox from mail_test)),0,'provider retries never become new application attempts');
with inserted as(insert into app_private.email_outbox(dedupe_key,message_type,recipient_ref,recipient_email,payload,status,attempts,lease_until) values('resend-crash-fixture','registration_received','fixture','crash@example.invalid','{}','processing',1,now()+interval '1 minute') returning id)
update mail_test set outbox=inserted.id from inserted;
update mail_test set envelope=api.worker_mail_prepare('test','mail/crash/1',config,outbox,'transactional','registration_received','crash@example.invalid','{"text":"frozen-before-crash"}',repeat('d',64),repeat('c',64));
update app_private.mail_envelopes set lease_until=now()-interval '1 second' where id=(select (envelope->>'id')::uuid from mail_test);
update app_private.email_outbox set lease_until=now()-interval '1 second' where id=(select outbox from mail_test);
select is((select count(*)::integer from api.worker_claim_outbox(50,10) where id=(select outbox from mail_test)),0,'a legacy worker can never recover a Resend row through SendGrid');
select is((select count(*)::integer from api.worker_claim_outbox(50,10,'test') where id=(select outbox from mail_test)),1,'worker crash inside the idempotency window recovers the existing Resend attempt');
select is(api.worker_mail_prepare('test','mail/crash/1',(select config from mail_test),(select outbox from mail_test),'transactional','registration_received','crash@example.invalid','{"text":"changed-after-crash"}',repeat('e',64),repeat('c',64))->'payload'->>'text','frozen-before-crash','lease recovery returns the original rendered body');
update app_private.mail_envelopes set status='unknown',lease_until=null,first_attempt_at=now()-interval '25 hours' where logical_key='mail/crash/1';
update app_private.email_outbox set status='deferred',lease_until=null,next_attempt_at=now()-interval '1 second' where id=(select outbox from mail_test);
select is((select count(*)::integer from api.worker_claim_outbox(50,10,'test') where id=(select outbox from mail_test)),0,'expired uncertain envelope cannot be reclaimed through deferred queue state');
select is((select status::text from app_private.email_outbox where id=(select outbox from mail_test)),'unknown','expired dedupe window is visible for manual reconciliation');

-- Unknown attempts preserve exact payload, key, provider, config and credentials.
update mail_test set envelope=api.worker_mail_prepare('test','auth/stable-opaque-identity',config,null,'auth','auth_otp','auth@example.invalid',null,repeat('d',64),repeat('c',64));
select api.worker_mail_finish((select (envelope->>'id')::uuid from mail_test),(select (envelope->>'claim_token')::uuid from mail_test),'unknown',null,'RESEND_NETWORK_UNCERTAIN');
update mail_test set envelope=api.worker_mail_prepare('test','auth/stable-opaque-identity',config,null,'auth','auth_otp','auth@example.invalid',null,repeat('d',64),repeat('c',64));
select is((select envelope->>'dispatch' from mail_test),'true','unknown Auth result is safely retried with the original identity inside the window');
select ok((select payload is null from app_private.mail_envelopes where logical_key='auth/stable-opaque-identity'),'no OTP body is stored in general envelope/event records');
update app_private.mail_envelopes set status='unknown',lease_until=null,first_attempt_at=now()-interval '25 hours' where logical_key='auth/stable-opaque-identity';
select is(api.worker_mail_prepare('test','auth/stable-opaque-identity',(select config from mail_test),null,'auth','auth_otp','auth@example.invalid',null,repeat('d',64),repeat('c',64))->>'status','reconcile','unknown after the 24h guarantee is never blindly resent');
select is(api.worker_mail_prepare('test','auth/rotated-credentials',(select config from mail_test),null,'auth','auth_otp','auth@example.invalid',null,repeat('d',64),repeat('c',64))->>'dispatch','true','first Auth attempt claims stable credential context');
update app_private.mail_envelopes set status='unknown',lease_until=null where logical_key='auth/rotated-credentials';
select is(api.worker_mail_prepare('test','auth/rotated-credentials',(select config from mail_test),null,'auth','auth_otp','auth@example.invalid',null,repeat('d',64),repeat('e',64))->>'status','reconcile','changed provider credentials cannot silently replay an uncertain request in another account');
select ok(not has_table_privilege('authenticated','app_private.mail_envelopes','select'),'browser cannot read Auth attempts or frozen payloads');
select ok(not has_function_privilege('authenticated','api.mail_admin_command(text,uuid,text,text,integer,uuid,jsonb,jsonb)','execute'),'browser cannot bypass runtime system-admin authorization');
select ok(not has_function_privilege('anon','api.worker_store_resend_event(text,text,text,text,timestamptz,text,text,text)','execute'),'anonymous callers cannot fake durable webhook receipts');
select ok(not has_function_privilege('service_role','api.worker_claim_outbox_before_resend(integer,integer)','execute'),'internal legacy claim wrapper is not independently callable');
select api.worker_import_mail_suppressions('test',jsonb_build_array(jsonb_build_object('emailHash',encode(extensions.digest('hard-bounce@example.invalid','sha256'),'hex'),'reason','bounce')),repeat('a',64));
select api.worker_import_mail_suppressions('test',jsonb_build_array(jsonb_build_object('emailHash',encode(extensions.digest('hard-bounce@example.invalid','sha256'),'hex'),'reason','unsubscribe')),repeat('a',64));
select ok((select transactional_blocked from app_private.mail_suppressions where environment='test' and recipient_hash=extensions.digest('hard-bounce@example.invalid','sha256')),'an unsubscribe import can never erase a hard bounce or complaint block');
select api.worker_import_mail_suppressions('test',jsonb_build_array(jsonb_build_object('emailHash',encode(extensions.digest('only-newsletter-unsub@example.invalid','sha256'),'hex'),'reason','unsubscribe')),repeat('a',64));
select is(api.worker_mail_prepare('test','auth/unsubscribed-newsletter-only',(select config from mail_test),null,'auth','auth_otp','only-newsletter-unsub@example.invalid',null,repeat('d',64),repeat('c',64))->>'dispatch','true','a newsletter unsubscribe does not block a separately requested Auth OTP');
select api.mail_admin_rollback('test' ,(select actor from mail_test),'duindorp-halloween-2026',2,true,'Gecontroleerde incidentele rollback van de nieuwe provider');
select is(api.worker_mail_config('test')->>'provider','sendgrid','explicit rollback chooses legacy only for new envelopes');
select is(api.worker_mail_config('test','auth/stable-opaque-identity')->>'provider','resend','rollback never re-routes an earlier uncertain Resend attempt');
select * from finish();
rollback;
